const rows = $input.all().map(i => i.json);

// Guard: wrong row count means the query or data changed. Throwing triggers the Error alert workflow.
if (rows.length !== 36) throw new Error(`Digest expected 36 rows, got ${rows.length}`);

const TITLE = {
  genre: 'Top genres (share of the region\'s sales, all years)',
  publisher: 'Top publishers (share of the region\'s sales, all years)',
  platform_2015: 'Top platforms in 2015 (share of the region\'s 2015 sales)',
};
const REGION = {
  NA: 'North America',
  EU: 'Europe',
  JP: 'Japan',
  Other: 'Other (a grouping of many markets, not one country)',
};

let table = '';
for (const metric of Object.keys(TITLE)) {
  table += `${TITLE[metric]}\n`;
  for (const region of Object.keys(REGION)) {
    const part = rows
      .filter(r => r.metric === metric && r.region === region)
      .sort((a, b) => Number(a.rnk) - Number(b.rnk))
      .map(r => `${r.rnk}. ${r.item} ${Number(r.sales_m).toFixed(2)}M (${r.share_pct}%)`);
    table += `  ${REGION[region]}: ${part.join('; ')}\n`;
  }
  table += '\n';
}

const prompt =
`You write a short weekly summary of video game sales by region.
Use ONLY the facts below. Do not add numbers, years or claims that are not listed.
Write exactly 5 sentences: one each for North America, Europe, Japan and Other (top genre and top publisher with their percentages), then one about the 2015 platforms.
Use platform names exactly as listed (PS4, not PlayStation 4). Do not forecast or predict.

FACTS:
${table}`;

return [{ json: { table, prompt } }];

const table = $('Code').first().json.table;   // <- exact name of the node that builds the table
let summary = String($input.first().json.text ?? '')
  .replace(/<think>[\s\S]*?<\/think>/g, '')
  .trim();

// HARD checks: throw so the Error alert workflow emails you instead of sending a bad digest
if (summary.length < 100) throw new Error(`Digest summary empty or too short (${summary.length} chars)`);

const nums = s => (s.match(/\d+(?:\.\d+)?/g) || []).map(Number);
const allowed = new Set(nums(table));
const invented = [...new Set(nums(summary).filter(n => !allowed.has(n)))];
if (invented.length) throw new Error(`Digest contains numbers not in the SQL table: ${invented.join(', ')}`);

// SOFT checks: still send, but flag them in the email
const warnings = [];
for (const r of ['North America', 'Europe', 'Japan', 'Other']) {
  if (!summary.includes(r)) warnings.push(`Summary does not mention ${r}`);
}
if (/\b(will|forecast|predict|expect|likely|future)\b/i.test(summary)) warnings.push('Summary may contain a forecast');
if (/\bOther\b[^.]*\bcountry\b/i.test(summary)) warnings.push('"Other" may be described as a country');

const email =
`WEEKLY VGSALES REGIONAL DIGEST
(Historical data through 2016, not live. Sales in millions of units.)

SUMMARY (written by llama3.1:8b)
${summary}

CHECKS: ${warnings.length ? 'WARNINGS: ' + warnings.join('; ') : 'all passed'}

SOURCE NUMBERS (from SQL)
${table}`;

return [{ json: { email, warnings } }];
